export async function createWebsiteBashConfiguration(applicationRootURL: string) {
  const application = new URL(applicationRootURL, globalThis.location.href);
  if (application.origin !== globalThis.location.origin || !application.pathname.endsWith('/') || application.search || application.hash || application.username || application.password) throw new Error('Invalid application asset root');
  const base = new URL('container-app/', application);
  const priorBase = new URL(release.baseURL);
  const distribution = structuredClone(release.distribution);
  for (const pkg of distribution.packages) for (const asset of pkg.assets) {
    const path = new URL(asset.url).pathname.slice(priorBase.pathname.length);
    if (!/^objects\/[a-f0-9]{64}\/[a-z0-9.-]+$/.test(path)) throw new Error('Invalid fixed container object');
    asset.url = new URL(path, base).href;
  }
  const manifest = JSON.stringify(distribution);
  const manifestSha256 = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(manifest))), n => n.toString(16).padStart(2, '0')).join('');
  const host = new URL('host/' + release.hostHash + '/', base);
  const config = { ...release.config, manifest, manifestSha256,
    assetURLs: distribution.packages.flatMap(pkg => pkg.assets.map(asset => asset.url)),
    sdkUrl: new URL('./sdk/index.mjs', host).href, sdkWorkerUrl: new URL('./sdk/worker.mjs', host).href,
    liveWorkerUrl: new URL('./live-worker.mjs', host).href, clangWorkerUrl: new URL('./clang-worker.mjs', host).href,
    commandTimeoutMs: undefined
  };
  // This URL comes from the compiled application's fixed host hash, never a guest or a fetched manifest.
  const sdk = await import(/* @vite-ignore */ config.sdkUrl);
  return { config, sdk };
}
